<script>(()=>{const base=<?=json_encode($base)?>,token=<?=json_encode($csrf)?>;async function post(url,fd){const r=await fetch(url,{method:'POST',body:fd,headers:{Accept:'application/json'}});return r.json().catch(()=>({success:false,message:'Request failed.'}))}document.querySelectorAll('[data-key]').forEach(b=>b.addEventListener('click',async()=>{const fd=new FormData();fd.append('_token',token);fd.append('key',b.dataset.key);fd.append('quantity',b.dataset.qty);const j=await post(base+'/member/fresh-food/cart/update',fd);if(j.success)location.reload();else alert(j.message||'Unable to update cart.')});document.getElementById('clearCart')?.addEventListener('click',async()=>{if(!confirm('Clear this Fresh Food cart?'))return;const fd=new FormData();fd.append('_token',token);const j=await post(base+'/member/fresh-food/cart/clear',fd);if(j.success)location.reload();else alert(j.message||'Unable to clear cart.')});document.getElementById('couponForm')?.addEventListener('submit',async e=>{e.preventDefault();const j=await post(base+'/member/fresh-food/coupon',new FormData(e.target));if(j.success)location.reload();else alert(j.message||'Coupon could not be applied.')});document.getElementById('removeCoupon')?.addEventListener('click',async()=>{const fd=new FormData();fd.append('_token',token);const j=await post(base+'/member/fresh-food/coupon/remove',fd);if(j.success)location.reload();else alert(j.message||'Unable to remove coupon.')});})();</script>
